const applyGallery = () => {
  let images = props.slides;
  if (typeof images === 'string') {
    try {
      images = JSON.parse(images);
    } catch (error) {
      images = [];
    }
  }
  if (!Array.isArray(images)) images = [];

  const staleWrapClone = track.querySelector('[data-carousel-clone]');
  if (staleWrapClone) staleWrapClone.remove();

  let currentSlides = slides();
  if (images.length > 0 && currentSlides.length > 0) {
    while (currentSlides.length < images.length) {
      const templateSlide = currentSlides[0];
      const newSlide = templateSlide.cloneNode(true);
      newSlide.setAttribute('data-carousel-dynamic', 'true');
      [newSlide, ...newSlide.querySelectorAll('[data-block-id]')].forEach((el) => el.removeAttribute('data-block-id'));
      track.appendChild(newSlide);
      currentSlides = slides();
    }
  }

  currentSlides.forEach((slide, index) => {
    if (images.length > 0) {
      if (index < images.length) {
        slide.style.display = '';
        const url = images[index];
        slide.style.backgroundImage = url ? 'url("' + url + '")' : '';
        slide.style.backgroundSize = url ? 'cover' : '';
        slide.style.backgroundPosition = url ? 'center' : '';
      } else {
        if (slide.hasAttribute('data-carousel-dynamic')) {
          slide.remove();
        } else {
